function traversalReferences(order) {
  const pythonStep = order === 'pre' ? 'out.append(n.val);walk(n.left);walk(n.right)' : 'walk(n.left);walk(n.right);out.append(n.val)';
  const managedStep = order === 'pre' ? 'o.add(n.val);walk(n.left,o);walk(n.right,o);' : 'walk(n.left,o);walk(n.right,o);o.add(n.val);';
  const jsStep = order === 'pre' ? 'out.push(n.val);walk(n.left);walk(n.right)' : 'walk(n.left);walk(n.right);out.push(n.val)';
  const nativeStep = order === 'pre' ? 'out[(*k)++]=n->val;walk(n->left,out,k);walk(n->right,out,k);' : 'walk(n->left,out,k);walk(n->right,out,k);out[(*k)++]=n->val;';
  const cppStep = order === 'pre' ? 'out[k++]=n->val;walk(n->left,out,k);walk(n->right,out,k);' : 'walk(n->left,out,k);walk(n->right,out,k);out[k++]=n->val;';
  const csharpStep = order === 'pre' ? 'o.Add(n.val);Walk(n.left,o);Walk(n.right,o);' : 'Walk(n.left,o);Walk(n.right,o);o.Add(n.val);';
  const phpStep = order === 'pre' ? '$o[]=$n->val;$walk($n->left);$walk($n->right);' : '$walk($n->left);$walk($n->right);$o[]=$n->val;';
  const rStep = order === 'pre' ? 'out<<-c(out,n$val);walk(n$left);walk(n$right)' : 'walk(n$left);walk(n$right);out<<-c(out,n$val)';
  const callable = order === 'pre' ? 'preorderTraversal' : 'postorderTraversal';
  return Object.freeze({
    python: `from __future__ import annotations\nclass TreeNode:\n def __init__(self,val=0,left=None,right=None):self.val,self.left,self.right=val,left,right\ndef ${callable}(root):\n out=[]\n def walk(n):\n  if n:${pythonStep}\n walk(root);return out`,
    java: `public class Solution{public static class TreeNode{public int val;public TreeNode left,right;public TreeNode(int v){val=v;}}void walk(TreeNode n,java.util.List<Integer>o){if(n!=null){${managedStep}}}public int[] ${callable}(TreeNode root){java.util.ArrayList<Integer>o=new java.util.ArrayList<>();walk(root,o);return o.stream().mapToInt(Integer::intValue).toArray();}}`,
    javascript: `class TreeNode{constructor(val=0,left=null,right=null){this.val=val;this.left=left;this.right=right}}function ${callable}(root){const out=[];function walk(n){if(n){${jsStep}}}walk(root);return out}`,
    typescript: `class TreeNode{constructor(public val=0,public left:TreeNode|null=null,public right:TreeNode|null=null){}}function ${callable}(root:TreeNode|null):number[]{const out:number[]=[];function walk(n:TreeNode|null){if(n){${jsStep}}}walk(root);return out}`,
    c: `#include <stdbool.h>\n#include <stddef.h>\n#include <stdint.h>\n#include <stdlib.h>\ntypedef struct TreeNode{int32_t val;struct TreeNode*left,*right;}TreeNode;typedef struct{int32_t*data;size_t len;}IntArray;static void walk(TreeNode*n,int32_t*out,size_t*k){if(n){${nativeStep}}}IntArray ${callable}(TreeNode*root){int32_t*out=malloc(256*sizeof(int32_t));size_t n=0;walk(root,out,&n);return(IntArray){out,n};}`,
    cpp: `#include <cstddef>\n#include <cstdint>\n#include <cstdlib>\ntypedef struct TreeNode{int val;struct TreeNode*left,*right;}TreeNode;typedef struct{int*data;std::size_t len;}IntArray;static void walk(TreeNode*n,int*out,std::size_t&k){if(n){${cppStep}}}IntArray ${callable}(TreeNode*root){int*out=(int*)std::malloc(256*sizeof(int));std::size_t n=0;walk(root,out,n);return{out,n};}`,
    csharp: `public class Solution{public class TreeNode{public int val;public TreeNode left,right;public TreeNode(int v){val=v;}}void Walk(TreeNode n,System.Collections.Generic.List<int>o){if(n!=null){${csharpStep}}}public int[] ${callable}(TreeNode root){var o=new System.Collections.Generic.List<int>();Walk(root,o);return o.ToArray();}}`,
    php: `<?php class TreeNode{function __construct(public int $val=0,public ?TreeNode $left=null,public ?TreeNode $right=null){}}function ${callable}(?TreeNode $root):array{$o=[];$walk=function($n)use(&$walk,&$o){if($n){${phpStep}}};$walk($root);return $o;}`,
    r: `TreeNode<-function(val=0L,left=NULL,right=NULL){n<-new.env(parent=emptyenv());n$val<-val;n$left<-left;n$right<-right;n};${callable}<-function(root){out<-integer();walk<-function(n){if(!is.null(n)){${rStep}}};walk(root);out}`,
  });
}

